#pragma once

// Offline split-effect filter tags for the split picker (分割线筛选).
// Data: ui/src/regions/edit/split_effect_tags.inc, generated by
// scripts/generate_split_effect_tags.py from catalog.json + the sprite theme
// table scripts/data/split_effect_sprite_themes.json + the picker snapshot
// table (pure-line detection). Runtime never parses JSON.

#include <cstdint>
#include <string>
#include <vector>

namespace wds::ui {

// Layer bits (bits 0..15): which particle-system kinds an effect contains.
inline constexpr uint32_t kSplitTagSparkle = 1u << 0;   // 闪光: cross/star sparkle billboards
inline constexpr uint32_t kSplitTagSmoke = 1u << 1;     // 烟雾: smoke / cloud / splash / flame billboards
inline constexpr uint32_t kSplitTagSolid = 1u << 2;     // 实体: ParticleAlpha (non-glowing) particles
inline constexpr uint32_t kSplitTagStreak = 1u << 3;    // 流光: Stretched billboards
inline constexpr uint32_t kSplitTagRibbon = 1u << 4;    // 丝带: Trails mode Ribbon
inline constexpr uint32_t kSplitTagFirework = 1u << 5;  // 烟花: Trails mode PerParticle
inline constexpr uint32_t kSplitTagLineOnly = 1u << 6;  // 纯线: no particles in the picker snapshot
inline constexpr uint32_t kSplitTagLayerMask = 0x0000FFFFu;
// Theme bits (bits 16..31): kSplitTagThemeBase << i for theme i in
// split_effect_theme_tags() order. The theme list is data-driven.
inline constexpr uint32_t kSplitTagThemeBase = 1u << 16;
inline constexpr uint32_t kSplitTagThemeMask = 0xFFFF0000u;

struct SplitEffectTagInfo {
  uint32_t bit;
  const char* label_utf8;    // short chip text, 2 CJK chars
  const char* tooltip_utf8;  // one-line description
};

// UI order. Stable for the lifetime of the process.
const std::vector<SplitEffectTagInfo>& split_effect_layer_tags();
const std::vector<SplitEffectTagInfo>& split_effect_theme_tags();

// 0 for unknown ids.
uint32_t split_effect_tags(int32_t color_id) noexcept;

// Facet semantics: OR inside a group, AND across groups, AND-NOT for exclude.
// layer_any == 0 / theme_any == 0 means that group does not constrain.
struct SplitTagFilter {
  uint32_t layer_any = 0;
  uint32_t theme_any = 0;
  uint32_t exclude = 0;
  bool empty() const noexcept { return layer_any == 0 && theme_any == 0 && exclude == 0; }
};

bool split_effect_tags_match(uint32_t tags, const SplitTagFilter& filter) noexcept;

// Same id-substring search as filter_split_picker_color_ids(query), then the tag filter.
std::vector<int32_t> filter_split_picker_color_ids(const std::string& query,
                                                   const SplitTagFilter& filter);

}  // namespace wds::ui
